/* course17.js — Course 17 content (When the network does not work: troubleshooting; loaded on demand via course-core.js) */
/* ============================================================
   COURSE 17 — When the network does not work: troubleshooting (methodology, the physical layer,
   L2/VLANs, L3/gateway and routes, names and DNS, firewall rules).
   The course teaches no new technologies — it teaches PROCEDURE and uses existing simulator
   tasks (ch-down, ch-portvlan, ch-gw, dns-down, shadow-rule).
   Scene c17Net: PC-A/PC-B — SW — GW — FW — {WEB, DNS}.
   ============================================================ */
var C17R={pca:[62,124],pcb:[62,212],sw:[184,124],gw:[306,124],fw:[428,124],web:[566,62],dns:[566,190]};
function c17Net(pfx){
  return '<svg id="'+pfx+'svg" viewBox="0 0 640 288" width="100%" style="display:block">'
    +'<line x1="78" y1="124" x2="168" y2="124" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="78" y1="206" x2="170" y2="134" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="200" y1="124" x2="290" y2="124" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="322" y1="124" x2="412" y2="124" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="444" y1="116" x2="551" y2="70" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="444" y1="132" x2="551" y2="182" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<g id="'+pfx+'glow"></g>'
    +csHost(62,124,'desktop','--green','PC-A')
    +csHost(62,212,'desktop','--green','PC-B')
    +csDev(184,124,'l2switch','SW')
    +csDev(306,124,'router','GW')
    +csDev(428,124,'firewall','FW')
    +csHost(566,62,'server','--green','WEB')
    +csHost(566,190,'dns','--blue','DNS')
    +'<g id="'+pfx+'dyn"></g></svg>';
}
function c17P(pfx,intro,terms){
  return '<p style="color:var(--muted);font-size:var(--crs-fs,13.5px);line-height:1.55;margin:0 0 10px">'+intro+'</p>'
    +'<div class="osi-stage">'+c17Net(pfx)+'</div><div class="m1-cap" id="'+pfx+'cap"></div>'
    +courseStepControls(pfx)+abbrBox(terms);
}
function c17Mount(pfx,STEPS){
  function show(i){var g=$(pfx+'glow');if(g)g.innerHTML=STEPS[i].glow||'';var d=$(pfx+'dyn');if(d)d.innerHTML=STEPS[i].dyn||'';var c=$(pfx+'cap');if(c)c.innerHTML='<span>'+STEPS[i].cap+'</span>';}
  courseStepper(pfx,STEPS.length,show);
}
function c17g(name,color){var p=C17R[name];return csGlow(p[0],p[1],color,20);}
function c17lbl(x,y,tx,c){return '<text x="'+x+'" y="'+y+'" text-anchor="middle" style="font:700 7.5px var(--mono);fill:var('+c+')">'+esc(tx)+'</text>';}
function c17pkt(path,color,dur){return '<rect x="-6" y="-4" width="12" height="9" rx="2" style="fill:var('+color+')"><animateMotion path="'+path+'" dur="'+(dur||'1.4s')+'" repeatCount="indefinite"/></rect>';}

/* ---------- L1M1 — What actually happened ---------- */
function renderC17What(){return c17P('tsa',
  '<b>Before you start:</b> this course builds on basics from the beginner courses (addresses and mask, gateway, VLANs, ports, DNS, firewall) – if any feels unfamiliar, check those first. “The internet is down.” As a network admin you will hear this sentence more than any other – and it is simultaneously the least useful piece of information in the world. Before you touch a single device, you need to turn it into a <b>fault description</b> you can work with. Ask four things. <b>Who</b> has the problem: one person, one department, or the whole building? <b>What</b> exactly fails: a specific application, a specific website, or absolutely everything? <b>Since when</b> has it failed and <b>what changed before that</b> – a new wall socket, a new device, new rules, a replaced cable? And finally: <b>did it ever work</b>? A new thing that never worked is almost always a configuration mistake; a thing that worked this morning is a fault or someone’s change. While doing this, separate the <b>symptom</b> (what the user sees – “the page will not load”) from the <b>impact</b> (what it means for the business – “nobody can invoice”). The symptom helps you search, the impact tells you how much to hurry. And the most important habit right from the start: <b>write down</b> what you found and what you tried. In an hour you will not remember whether you already re-plugged that cable.',
  [['symptom','what the user sees and describes – the concrete manifestation, for example “the page will not load”.'],['impact','what the fault means for the business; it decides how urgent the case is.'],['fault description','who, what, since when and what changed – turning a complaint into verifiable facts.']]);}
function mountC17What(){c17Mount('tsa',[
  {glow:c17g('pca','--amber'),dyn:c17lbl(320,266,'user reports: “the internet is down”','--amber'),cap:'It starts with a sentence that says almost nothing. Your first job is not to fix, but to <b>find out what actually happened</b>.'},
  {glow:c17g('pca','--blue'),dyn:c17lbl(320,266,'who, what exactly, since when, what changed','--blue'),cap:'Ask four things: <b>who</b>, <b>what exactly</b> fails, <b>since when</b> and <b>what changed before</b>. Only that is a fault description.'},
  {glow:c17g('pca','--violet')+c17g('web','--violet'),dyn:c17lbl(320,266,'did it ever work at all?','--violet'),cap:'A new thing that never worked is usually a <b>configuration mistake</b>. A thing that worked this morning is usually <b>a fault or someone’s change</b>.'},
  {glow:c17g('pca','--cyan')+c17g('pcb','--cyan'),dyn:c17lbl(320,266,'the symptom searches, the impact sets urgency','--cyan'),cap:'Separate the <b>symptom</b> from the <b>impact</b> and <b>write everything down</b>. Without notes you will not know in an hour what you already tried.'}
]);}
/* ---------- L1M2 — Scope of the fault ---------- */
function renderC17Scope(){return c17P('tsb',
  'The second question after “what happened” is <b>how far it reaches</b>. The scope of a fault is the cheapest and most powerful tool you have: it <b>narrows the suspects before you touch anything</b>. Proceed simply. Does it fail for <b>one</b> user while the colleague next to them is fine? Then the fault is almost certainly <b>with them</b> – their cable, their switch port, their address settings, their application. Checking the router makes no sense; that would down everyone. Does it fail for <b>a whole group</b> (one floor, one VLAN, one switch)? Then look for what they share and others do not – a shared switch, a shared VLAN, a shared gateway. Does it fail for <b>absolutely everyone</b>? Then the fault is upstream, on the shared path: the gateway, the firewall, the provider link, DNS. And beware of a trap that catches nearly every beginner: <b>“it fails for everyone” does not mean “the whole network is broken”</b>. When a single DNS server goes down, everyone is affected, yet the network itself is perfectly fine – nobody can just turn a name into an address. So scope does not show you the culprit, but the <b>direction</b>: down toward the user, or up toward the shared devices.',
  [['fault scope','how many users or devices are affected; it shows whether to search at the user or on the shared path.'],['shared path','the devices and links all traffic passes through – the gateway, firewall, uplink, DNS.']]);}
function mountC17Scope(){c17Mount('tsb',[
  {glow:c17g('pca','--red')+c17g('pcb','--green'),dyn:c17lbl(320,266,'only PC-A: search at it (cable, port, address)','--red'),cap:'Fails for <b>one</b> user while the neighbor is fine? The fault is at them – their cable, port, settings. The router is innocent.'},
  {glow:c17g('pca','--amber')+c17g('pcb','--amber')+c17g('sw','--amber'),dyn:c17lbl(320,266,'a whole group: look for what they share','--amber'),cap:'Fails for <b>a whole group</b>? Look for what they share and others do not – one switch, one VLAN, one gateway.'},
  {glow:c17g('gw','--red')+c17g('fw','--red'),dyn:c17lbl(320,266,'fails for everyone: suspect the shared path','--red'),cap:'Fails for <b>everyone</b>? Suspect the shared path above: the gateway, the firewall, the uplink. All traffic meets there.'},
  {glow:c17g('dns','--violet'),dyn:c17lbl(320,266,'trap: everyone affected, yet the network is fine','--violet'),cap:'Trap: “it fails for everyone” ≠ “the network is broken”. When <b>DNS</b> is silent, all suffer, yet paths and addresses work fine.'}
]);}
/* ---------- L1M3 — Bottom-up, top-down, bisection ---------- */
function renderC17Method(){return c17P('tsc',
  'Now the main thing: <b>in what order</b> to search. Without an order, troubleshooting turns into guessing and random clicking – the fastest route to being back at the start an hour later, having broken something extra. Three approaches are used. <b>Bottom-up</b>: you begin at the physical layer (cable, port, link state), then addresses and gateway, then names, finally applications and rules. It is slower, but it <b>never skips</b> the stupid cause, which is the most common one. It fits when you know nothing at all, or the report is “nothing works”. <b>Top-down</b>: you begin at the application (“does anything else open?”) and descend. It fits when the network is obviously up – other people are working, only one service misbehaves. And third, a technique you will use constantly: <b>halving the problem</b>. You split the path from the PC to the target and test the <b>middle</b>: does a packet at least reach the gateway? If yes, the whole lower half is healthy and you can stop worrying about it. If no, the upper half is irrelevant. Each such test <b>discards half the suspects</b>, so even a long path takes only a few tries. The golden rule at the end: <b>change one thing at a time</b> and verify immediately what it did. Three changes at once means you no longer know which one helped – or whether another broke something else.',
  [['bottom-up','working from cable and port through addresses and names up to the application; it never skips a banal cause.'],['top-down','working from the application downward; it fits when the network as a whole is obviously working.'],['halving the problem','a test in the middle of the path discards half the suspect places at once.']])
  +courseCTA('tscTask','Try the method for real on a “server is unreachable” report: the task "The server is unreachable".','Open the task');}
function mountC17Method(){c17Mount('tsc',[
  {glow:c17g('pca','--green')+c17g('sw','--green'),dyn:c17lbl(320,266,'bottom-up: cable, port, address, name','--green'),cap:'<b>Bottom-up</b>: cable and port, then addresses and gateway, then names, finally the app. Slow, but it never skips the stupid cause.'},
  {glow:c17g('web','--blue')+c17g('fw','--blue'),dyn:c17lbl(320,266,'top-down: from the application toward the wire','--blue'),cap:'<b>Top-down</b>: start at the application and descend. It fits when others work normally and only one service misbehaves.'},
  {glow:c17g('pca','--amber')+c17g('sw','--amber')+c17g('gw','--amber'),dyn:c17pkt('M 62 124 L 184 124 L 306 124','--amber')+c17lbl(320,266,'halving: does a packet at least reach the gateway?','--amber'),cap:'<b>Halving</b>: test the middle of the path. Does a packet reach the gateway? Then the lower half is healthy and you cross it off.'},
  {glow:c17g('pca','--cyan')+c17g('sw','--cyan')+c17g('gw','--cyan')+c17g('fw','--cyan')+c17g('web','--cyan'),dyn:c17pkt('M 62 124 L 184 124 L 306 124 L 428 124 L 566 62','--cyan')+c17lbl(320,266,'change one thing and verify at once','--cyan'),cap:'The golden rule: <b>change one thing</b> and verify at once. After three changes you know neither which helped nor what you broke.'}
]);
  var b=$('tscTask');if(b)b.onclick=function(){courseTry('ch-down');};
}
/* ---------- L2M1 — Cable, port, link state ---------- */
function renderC17Phys(){return c17P('tsd',
  'Bottom-up starts where it is least elegant and most often correct: at <b>physics</b>. The statistics are merciless – a huge share of “the network is down” reports ends at an unplugged, loose or broken <b>cable</b>. Three terms worth keeping apart (this application uses them consistently): the <b>cable</b> is the physical thing between the sockets; the <b>link on the canvas</b> is the line between two devices as you see it; and the <b>line</b> is that connection’s parameters – speed and a possible outage. What to check, in this order. <b>1) Is the cable plugged in</b> at both ends? The user moved their desk, the cleaner pulled the plug – these are not jokes, this is Thursday. <b>2) Is the port up?</b> If the port reports the connection is running (link up), the physical layer has done its job. If it reports link down, examining anything else is pointless – no VLAN setting and no route will revive a dead cable. <b>3) Does traffic flow both ways?</b> There are nastier cases where the connection is “up” but the line is misconfigured or damaged and part of the frames get lost – that shows up as a slow, unreliable network, not as a total outage. In the simulator you see the connection state right on the canvas, and on a line you can set speed and an outage – that is your physical layer.',
  [['cable','the physical connection between two sockets; the most common cause of “the network is down”.'],['link (canvas)','the line between two devices on the canvas – that they are connected at all.'],['line','the connection’s parameters: speed and a possible outage; it can be bad even while the connection is up.']]);}
function mountC17Phys(){c17Mount('tsd',[
  {glow:c17g('pca','--green')+c17g('sw','--green'),dyn:c17pkt('M 62 124 L 184 124','--green')+c17lbl(320,266,'a healthy connection: frames flow both ways','--green'),cap:'The healthy state: the cable is in both sockets, the port reports the connection is up, and frames flow both ways.'},
  {glow:c17g('pca','--red'),dyn:c17lbl(320,266,'cable unplugged → the port reports link down','--red'),cap:'The single most common cause: an <b>unplugged or broken cable</b>. The port reports link down and you need look no further.'},
  {glow:c17g('sw','--amber'),dyn:c17lbl(320,266,'link down: no VLAN or route will fix it','--amber'),cap:'While the link is down, VLANs, addresses and routes are pointless to examine. <b>No setting revives a dead cable.</b>'},
  {glow:c17g('sw','--violet')+c17g('gw','--violet'),dyn:c17pkt('M 184 124 L 306 124','--violet','2.6s')+c17lbl(320,266,'the connection is up, but the line loses frames','--violet'),cap:'The nasty case: the connection is “up”, but the <b>line</b> loses some frames. It looks like a slow network, not an outage.'}
]);}
/* ---------- L2M2 — A disabled port and admin down ---------- */
function renderC17AdminDown(){return c17P('tse',
  'There is a fault that looks exactly like a cut cable, but the cause is elsewhere: the port has been <b>switched off by an administrator</b>. The technical term is <b>administratively down</b> (“admin down”) and it means the hardware is fine, the cable is plugged in, but the device has been told <b>not to use</b> that port. Why would anyone do that? For many, usually legitimate, reasons: unused ports are disabled <b>deliberately for security</b> (nobody can plug anything into a dead meeting-room socket), a port is disabled <b>temporarily for maintenance</b> and someone forgets to restore it, or <b>a protection mechanism disables it</b> after spotting something suspicious. How do you tell it apart from an unplugged cable? By <b>how the device describes the state</b>: a broken cable is reported as “the connection is not running”, while a disabled port reports “switched off by the administrator” – that is, as a <b>decision</b>, not a fault. And that is exactly why it deserves its own module: mistake it for a bad cable and you will spend half an hour replacing something that is perfectly fine. One more warning at the end: before you enable the port, <b>find out why it was disabled</b>. If someone shut it because of a security incident, your “fix” has just reopened that incident.',
  [['admin down','the port is off by an administrator’s decision, not by a fault; hardware and cable are fine.'],['disabling unused ports','a common security measure: nobody can connect through a dead socket.']]);}
function mountC17AdminDown(){c17Mount('tse',[
  {glow:c17g('pca','--red')+c17g('sw','--red'),dyn:c17lbl(320,266,'it looks just like a cut cable','--red'),cap:'PC-A is cut off and the symptom matches a bad cable. Except the cable is plugged in and the hardware is fine.'},
  {glow:c17g('sw','--amber'),dyn:c17lbl(320,266,'the port is off by the admin (admin down)','--amber'),cap:'The cause is elsewhere: the port is <b>administratively down</b>. The device reports a decision, not a link fault.'},
  {glow:c17g('sw','--violet')+c17g('pcb','--violet'),dyn:c17lbl(320,266,'unused ports are disabled on purpose','--violet'),cap:'Disabled ports are often <b>intentional</b>: an empty meeting-room socket, maintenance, or a protection response to something suspicious.'},
  {glow:c17g('sw','--green')+c17g('pca','--green')+c17g('gw','--green'),dyn:c17pkt('M 62 124 L 184 124 L 306 124','--green')+c17lbl(320,266,'first find out why, only then enable','--green'),cap:'Enabling the port fixes it in a second – but <b>first find out why it was off</b>, so you do not reopen an incident.'}
]);}
/* ---------- L2M3 — When one link is faulty ---------- */
function renderC17BadLink(){return c17P('tsf',
  'The last physical case is the trickiest, because it <b>does not look like a network fault</b>. One connection somewhere in the middle is faulty or overloaded: it does not go down, but <b>part of the frames vanish along the way</b>. Users describe it in entirely different words: “the internet feels slow”, “the call stutters”, “downloads keep breaking”, “the page loads on the second try”. Nobody says “we have a line fault” – which is precisely why such a thing takes so long to find. How to approach it? Use <b>scope and halving</b> from the first lesson. A faulty connection affects <b>everyone</b> who crosses it and nobody else – so when you notice that the people with problems happen to be exactly those whose traffic runs through one particular stretch, you have your suspect. Then test in pieces: first the device <b>before</b> the suspect connection, then the one behind it. If the nearer target is fine while the farther one behaves unreliably, the fault lies between them. And beware of two classic traps. First: <b>an occasional lost packet is not a fault</b> – networks routinely drop some traffic and upper layers resend it; a fault is only <b>repeated</b>, measurable loss. Second: before you start swapping hardware, <b>verify that more traffic is not simply crossing that connection than it can carry</b>. An overloaded line looks faulty, but the cable is not to blame.',
  [['packet loss','part of the traffic vanishes en route; occasional loss is normal, repeated loss means a fault or overload.'],['congested line','more traffic crosses the connection than it can carry; it looks like bad hardware, but the cause is capacity.']])
  +courseCTA('tsfTask','Walk the whole path from client to target and find where it breaks: the task "The server is unreachable".','Open the task');}
function mountC17BadLink(){c17Mount('tsf',[
  {glow:c17g('sw','--amber')+c17g('gw','--amber'),dyn:c17pkt('M 184 124 L 306 124','--amber','2.8s')+c17lbl(320,266,'the connection is up, it just loses frames','--amber'),cap:'A faulty connection does not go down – part of the <b>frames simply vanish</b>. Users report “slow internet” or “a stuttering call”.'},
  {glow:c17g('pca','--red')+c17g('pcb','--red'),dyn:c17lbl(320,266,'everyone crossing it is affected','--red'),cap:'Scope helps: a faulty connection affects <b>everyone who crosses it</b> and nobody else. That is your suspect stretch.'},
  {glow:c17g('pca','--green')+c17g('sw','--green')+c17g('fw','--red'),dyn:c17pkt('M 62 124 L 184 124','--green')+c17lbl(320,266,'the nearer target is fine, the farther one is not','--green'),cap:'Test in pieces: the target <b>before</b> the suspect connection, then behind it. The fault sits between the last good and first bad.'},
  {glow:c17g('gw','--violet')+c17g('fw','--violet'),dyn:c17lbl(320,266,'repeated loss counts, occasional does not','--violet'),cap:'Two traps: <b>occasional packet loss is normal</b> and <b>an overloaded line looks faulty</b>. Check both before swapping hardware.'}
]);
  var b=$('tsfTask');if(b)b.onclick=function(){courseTry('ch-down');};
}
/* ---------- L3M1 — Access port in the wrong VLAN ---------- */
function renderC17WrongVlan(){return c17P('tsg',
  'The cable is fine, the port is up – and still the PC gets nowhere. Welcome to layer two, home of one of the most common and most treacherous faults there is: <b>the port is in the wrong VLAN</b>. A one-line reminder of what that means (you know it in depth from the <b>Switching and VLANs</b> course): a <b>VLAN</b> splits one physical switch into several separate networks, and each <b>access port</b> belongs to exactly one of them. When someone moves a port from VLAN 10 to VLAN 20 – by mistake while re-patching, or through automation that classified the device elsewhere – the computer suddenly finds itself in an <b>entirely different network</b>. And here is the treachery: <b>from the outside everything looks healthy</b>. The cable holds, the port is up, the device may even get an address (just from a different range, because a different network hands it out). The user merely reports being unable to reach a server they used yesterday. There are two telltale signs. First: the PC has an <b>address from a different range</b> than its colleagues in the same office. Second: the PC sees devices it has no business seeing, and cannot see “its own”. And beware of the trap this fault sets: <b>it looks like an addressing problem</b>, and many people start rewriting the IP address by hand. That only masks the problem – the device still sits in the wrong network and keeps behaving oddly. The fix belongs <b>on the switch port</b>, not in the computer’s settings.',
  [['access port','a switch port belonging to a single VLAN; the device behind it is in that network and no other.'],['wrong VLAN','a port assigned elsewhere than intended; it looks healthy, but the device sits in a foreign network.']]);}
function mountC17WrongVlan(){c17Mount('tsg',[
  {glow:c17g('pca','--green')+c17g('sw','--green'),dyn:c17lbl(320,266,'cable holds, port is up – physics is fine','--green'),cap:'The physical layer is clean: the cable holds, the port is up. Still PC-A gets nowhere – we look further up.'},
  {glow:c17g('sw','--red')+c17g('pca','--amber'),dyn:c17lbl(320,266,'the port was moved to another VLAN','--amber'),cap:'Someone <b>moved the access port to another VLAN</b>. The computer landed in a whole different network with nothing physically changed.'},
  {glow:c17g('pca','--violet')+c17g('pcb','--green'),dyn:c17lbl(320,266,'an address from a different range than colleagues','--violet'),cap:'The telltale sign: PC-A has an <b>address from a different range</b> than the colleague next door and sees foreign devices.'},
  {glow:c17g('sw','--cyan')+c17g('pca','--cyan')+c17g('gw','--cyan'),dyn:c17pkt('M 62 124 L 184 124 L 306 124','--cyan')+c17lbl(320,266,'fix the switch port, not the PC address','--cyan'),cap:'The trap: it looks like an addressing problem. Rewriting the IP only masks it – <b>fix the port assignment on the switch</b>.'}
]);}
/* ---------- L3M2 — A trunk that does not carry what it should ---------- */
function renderC17Trunk(){return c17P('tsh',
  'When VLANs stretch across several switches, a <b>trunk</b> connects them – a link that carries traffic of <b>several VLANs at once</b> between devices, each frame tagged with the VLAN it belongs to. And because a trunk has its own list of <b>allowed VLANs</b>, a peculiar fault appears here: the trunk is up, the connection is healthy, frames flow across it – but <b>your particular VLAN is not allowed on it</b>, so its frames never reach the other side. The symptom is very specific and worth memorizing: <b>everything works inside one switch, nothing works between switches</b>, and only for some groups of users, while other VLANs happily cross the very same connection. Someone searching blindly can chase this all day, because every individual device looks correctly configured. The second classic form of the same fault is a <b>mismatch at the two ends</b>: one end of the connection is set as a trunk, the other as an ordinary access port. Then frames of one VLAN arrive where they should not, and others vanish entirely. So the procedure is simple: first confirm the problem really <b>crosses the boundary between switches</b> (fine inside, broken outward), and only then look at <b>both ends of the trunk</b> – whether both are trunks and whether both allow the <b>same</b> set of VLANs.',
  [['trunk','a link carrying several VLANs at once; each frame carries the tag of its VLAN.'],['allowed VLANs','the list of VLANs allowed to cross the trunk; a missing VLAN simply does not get through.']]);}
function mountC17Trunk(){c17Mount('tsh',[
  {glow:c17g('pca','--green')+c17g('pcb','--green')+c17g('sw','--green'),dyn:c17pkt('M 62 124 L 184 124 L 62 212','--green')+c17lbl(320,266,'inside one switch everything works','--green'),cap:'Inside one switch everything works. That is important information: addresses and ports are most likely fine.'},
  {glow:c17g('sw','--red')+c17g('gw','--red'),dyn:c17lbl(320,266,'outward it fails – only for one VLAN','--red'),cap:'Outward it fails, though – and <b>only for one group</b>. Other VLANs cross the same connection without trouble.'},
  {glow:c17g('sw','--amber'),dyn:c17lbl(320,266,'the trunk is up but does not allow this VLAN','--amber'),cap:'The cause: the trunk is up, but <b>your VLAN is not allowed on it</b>. Its frames simply never reach the other side.'},
  {glow:c17g('sw','--cyan')+c17g('gw','--cyan'),dyn:c17pkt('M 184 124 L 306 124','--cyan')+c17lbl(320,266,'check both trunk ends, not just one','--cyan'),cap:'Check <b>both ends</b>: whether both are trunks and allow the same VLAN set. A mismatch of ends is the second classic.'}
]);}
/* ---------- L3M3 — Where the frame is lost ---------- */
function renderC17FrameLost(){return c17P('tsi',
  'Let us condense layer two into a procedure you can use whenever “physics is fine but it still fails”. Ask: <b>how far does the frame get and where does it end?</b> Look for the answer in three steps. <b>1) Do two devices in the same VLAN see each other?</b> If yes, switching inside works and the problem is higher up (addresses, gateway, routes, rules). If no, you are in the right place. <b>2) Are they really in the same VLAN?</b> Check the assignment of <b>both</b> ports – not only the one someone complained about. A classic mistake is fixing the user’s port and missing that it was actually the server’s port that moved. <b>3) Must the frame cross the boundary between switches?</b> Then look at the trunk and the allowed VLANs. Add two things that get mixed into layer two and deserve a quick check: <b>port security features</b> (a protection that blocks the port when an unexpected device shows up behind it – the port then looks dead although the cable is fine) and the already mentioned <b>configuration mismatch at the two ends</b> of one connection. And finally a rule that saves you many dead ends: <b>when two devices cannot see each other even within one VLAN, worrying about the gateway or routes is pointless</b>. Move up there only once you know the lower floor holds.',
  [['same VLAN','the basic layer-two test: two devices in one VLAN must see each other without a router.'],['port security','a feature blocking the port on an unexpected device; the port then looks dead.']])
  +courseCTA('tsiTask','Find out why a computer is on the wrong network and fix it in the right place: the task "The PC is on the wrong network".','Open the task');}
function mountC17FrameLost(){c17Mount('tsi',[
  {glow:c17g('pca','--green')+c17g('pcb','--green')+c17g('sw','--green'),dyn:c17pkt('M 62 124 L 184 124 L 62 212','--green')+c17lbl(320,266,'step 1: do two devices in one VLAN see each other?','--green'),cap:'Step 1: do two devices <b>in the same VLAN</b> see each other? If yes, layer two holds and the problem is higher.'},
  {glow:c17g('sw','--amber')+c17g('pcb','--amber'),dyn:c17lbl(320,266,'step 2: check both ports, not just one','--amber'),cap:'Step 2: verify <b>both</b> port assignments. A common mistake: you fix the user’s port when the server’s port moved.'},
  {glow:c17g('sw','--red')+c17g('gw','--red'),dyn:c17lbl(320,266,'step 3: does the frame cross a switch boundary?','--red'),cap:'Step 3: must the frame <b>cross the boundary between switches</b>? Then look at the trunk and the allowed VLANs.'},
  {glow:c17g('gw','--violet')+c17g('fw','--violet'),dyn:c17lbl(320,266,'without L2 there is no point asking about routes','--violet'),cap:'A closing rule: while devices cannot see each other in one VLAN, <b>leave the gateway and routes alone</b>. Move up only after verifying.'}
]);
  var b=$('tsiTask');if(b)b.onclick=function(){courseTry('ch-portvlan');};
}
/* ---------- L4M1 — Wrong IP or mask ---------- */
function renderC17BadIp(){return c17P('tsj',
  'Layer three starts by asking whether the device even has a <b>sensible address</b>. Three cases cover nearly everything. <b>The address is missing entirely</b> – the device was to get one automatically but did not (assignment is broken, or it cannot reach the server handing addresses out). It is easy to spot: the device assigns itself a fallback address that gets it nowhere. <b>The address is from a different range</b> than it should be – either someone typed it in wrong, or the device is in the wrong VLAN (which you can now find from the previous lesson). <b>The mask is wrong</b> – and this is the subtle variant worth dissecting. The mask says which part of the address is the <b>network number</b>: by it the device decides whether the target is <b>on its own network</b> (send directly) or <b>elsewhere</b> (send to the gateway). When the mask is too narrow, the device treats its own neighbors as strangers and needlessly sends to them via the gateway. When it is too wide, it treats devices from other networks as neighbors, tries to address them directly – and the reply never comes. The result is eerie either way: <b>some things work and some do not</b>, with no obvious logic. And when two devices have matching addresses but <b>differing masks</b>, they may see each other in one direction only. So always check the <b>address and mask together</b>, never just the address.',
  [['subnet mask','it defines which part of the address is the network number; by it a device decides “neighbor or via the gateway”.'],['fallback address','an address a device assigns itself when it gets none; it gets nowhere with it.']]);}
function mountC17BadIp(){c17Mount('tsj',[
  {glow:c17g('pca','--red'),dyn:c17lbl(320,266,'no address: the device assigns itself a fallback','--red'),cap:'Case one: the address is <b>missing entirely</b>. The device assigns itself a fallback address that gets it nowhere.'},
  {glow:c17g('pca','--amber')+c17g('sw','--amber'),dyn:c17lbl(320,266,'an address from a different range than intended','--amber'),cap:'Case two: the address is <b>from a different range</b>. Either someone typed it manually, or the device is in the wrong VLAN.'},
  {glow:c17g('pca','--violet')+c17g('sw','--violet')+c17g('gw','--violet'),dyn:c17pkt('M 62 124 L 184 124 L 306 124','--violet')+c17lbl(320,266,'narrow mask: a neighbor is sent via the gateway','--violet'),cap:'A mask that is too <b>narrow</b>: the device treats its own neighbors as strangers and needlessly routes them via the gateway.'},
  {glow:c17g('pca','--red')+c17g('web','--red'),dyn:c17lbl(320,266,'wide mask: a stranger is addressed directly','--red'),cap:'A mask that is too <b>wide</b>: the device addresses a foreign network directly and gets no reply. Always check <b>address and mask</b>.'}
]);}
/* ---------- L4M2 — Missing or wrong gateway ---------- */
function renderC17Gateway(){return c17P('tsk',
  'Memorize this symptom, because it is <b>utterly typical</b>: a device <b>sees everything on its own network but nothing outside it</b>. The colleague next door answers, the shared printer works, but a server in another network and the internet do not exist. Almost always the <b>default gateway</b> is to blame – the address of the device to which the computer hands everything that is not on its own network. The mistake takes three forms. <b>The gateway is missing</b>: the computer has nowhere to send outbound traffic, so it simply does not send it. <b>The gateway address is wrong</b>: it points to a device that does not exist or cannot route; traffic leaves and never arrives. <b>The gateway is outside its own network</b>: the address is valid but, by the mask, sits in a different network – which the computer cannot reach, because reaching it would again require a gateway. In numbers: the computer has 192.168.1.20 with a /24 mask, so its network is 192.168.1.0 – but its configured gateway is 192.168.2.1, which by the same mask belongs to a different network (192.168.2.0). It cannot address it directly, nor via a gateway, because that gateway IS the one in question. A classic circular absurdity that looks innocent in the configuration. Test in this order. First verify you can reach <b>the gateway</b>: if not, you are back in layer two (VLAN, port, cable). If yes, try something <b>beyond the gateway</b>. And if you reach the gateway but no further, you have narrowed it to two options: <b>the gateway does not route where it should</b> (the next module), or something along the way <b>discards the traffic</b> (the final lesson). A closing note: when <b>one</b> computer has a wrong gateway, the mistake is in its settings; when <b>everyone</b> has it, what hands it out is wrong.',
  [['default gateway','the address of the device a computer hands off traffic destined outside its own network.'],['the typical symptom','I see everything on my network and nothing outside it – it almost always leads to the gateway.']]);}
function mountC17Gateway(){c17Mount('tsk',[
  {glow:c17g('pca','--green')+c17g('pcb','--green')+c17g('sw','--green'),dyn:c17pkt('M 62 124 L 184 124 L 62 212','--green')+c17lbl(320,266,'within its own network everything works','--green'),cap:'The typical symptom, part one: <b>within its own network everything works</b>. The colleague answers, the printer prints.'},
  {glow:c17g('pca','--red')+c17g('web','--red'),dyn:c17lbl(320,266,'outside the network nothing exists at all','--red'),cap:'Part two: <b>outside the network nothing exists</b> – no server, no internet. This pair almost always points at the gateway.'},
  {glow:c17g('gw','--amber'),dyn:c17lbl(320,266,'gateway missing, wrong, or outside the network','--amber'),cap:'Three forms: the gateway is <b>missing</b>, <b>mistyped</b>, or <b>outside its own network</b> – and thus unreachable.'},
  {glow:c17g('pca','--cyan')+c17g('sw','--cyan')+c17g('gw','--cyan')+c17g('fw','--cyan'),dyn:c17pkt('M 62 124 L 184 124 L 306 124 L 428 124','--cyan')+c17lbl(320,266,'first to the gateway, only then beyond it','--cyan'),cap:'Procedure: try the <b>gateway</b> first, then something <b>beyond it</b>. Gateway fine but nothing further leaves a route or a rule.'}
]);}
/* ---------- L4M3 — Missing route ---------- */
function renderC17Route(){return c17P('tsl',
  'You reached the gateway but no further. Now the <b>route</b> enters – an entry in the routing table telling the router “send traffic for this network this way”. When a route is missing, the router <b>has nowhere to hand the packet</b> and drops it. And here is the crucial difference from the earlier faults: <b>a missing route need not be on your side</b>. Traffic is bidirectional. Your request may reach the target perfectly well – but if the target’s router <b>does not know the way back</b> to your network, the reply never returns. From the outside it looks as if the target were dead. So watch for this pattern: <b>“I get no reply” does not automatically mean “the request never arrived”</b>. The second typical form is <b>asymmetry</b>: it works from one network and not from another, because only one half of the pair of paths is missing. How to search in practice? Use <b>halving</b>. Watch how far the traffic gets – the last device that still answers is your marker. <b>The fault lies between the last one that replies and the first one that stays silent.</b> Then look at that device’s routing table: does it know the way to the target network? And does the target know the way back? In the simulator you have a big advantage over a real network – you see the whole topology at once, so you can literally trace the path with your finger and compare it against what the individual routers know. And from now on the path test does it for you: the result includes a <b>Route (traceroute)</b> block – device by device, with the TTL counting down. Where the route stops, that is where to look.',
  [['route','an entry in the routing table: “send traffic for this network this way”. Without it the router drops the packet.'],['return path','the route on the far side; when missing, the request arrives but the reply never returns.']])
  +courseCTA('tslTask','Find why a computer cannot get off its own network and fix it: the task "The PC can’t get off its network".','Open the task');}
function mountC17Route(){c17Mount('tsl',[
  {glow:c17g('pca','--green')+c17g('sw','--green')+c17g('gw','--green'),dyn:c17pkt('M 62 124 L 184 124 L 306 124','--green')+c17lbl(320,266,'you reach the gateway, but no further','--green'),cap:'The starting state: you reach the gateway but no further. Now the <b>routing table</b> enters the picture.'},
  {glow:c17g('gw','--red'),dyn:c17lbl(320,266,'route missing → the router drops the packet','--red'),cap:'When the <b>route is missing</b>, the router has nowhere to hand the packet and drops it. The target is perfectly fine.'},
  {glow:c17g('web','--amber')+c17g('fw','--amber')+c17g('pca','--amber')+c17g('sw','--amber')+c17g('gw','--amber'),dyn:c17pkt('M 62 124 L 184 124 L 306 124 L 428 124 L 566 62','--amber')+c17lbl(320,266,'the request arrives, but the return path is missing','--amber'),cap:'The catch: the request arrives, but the far side <b>knows no way back</b> – the reply never returns and the target looks dead.'},
  {glow:c17g('gw','--cyan')+c17g('fw','--cyan'),dyn:c17lbl(320,266,'the fault is between last good and first silent','--cyan'),cap:'Procedure: watch how far traffic gets. <b>The fault lies between the last device that replies and the first that stays silent.</b>'}
]);
  var b=$('tslTask');if(b)b.onclick=function(){courseTry('ch-gw');};
}
/* ---------- L5M1 — Test by name vs. by address ---------- */
function renderC17NameVsIp(){return c17P('tsm',
  'There is one test that can settle a huge share of “the internet is down” reports <b>in ten seconds</b> – and it is so simple that beginners skip it. It goes: <b>try it by name, then try the same thing by address</b>. A reminder of why. People use <b>names</b> (you type a website address), but the network knows only <b>numbers</b> (IP addresses). <b>DNS</b> does the translation. That means every “open this page” is really <b>two separate operations</b>: first translate the name to an address, only then connect to that address. And when one of the two fails, the user describes it identically – “it does not work”. The test reveals which one it was. <b>The name fails, the address works</b> → the network is healthy, paths and rules are fine, what is broken is <b>name resolution</b>. Stop searching the network, go straight to DNS. <b>Neither works</b> → the problem is in the network; go back to cables, VLANs, gateway and routes from the earlier lessons. <b>The name works, the address does not</b> → a rarity, but it happens: usually a different address hides behind the name (because the target has several addresses, or the one you tried is stale). Remember this test as a <b>signpost</b>: it fixes nothing, but within moments it tells you <b>which half of the world to search</b>. That is the most valuable information at the start.',
  [['name resolution','turning a name into an IP address via DNS; it is a separate step before the connection itself.'],['name vs address test','a signpost: it separates a network fault from a name-resolution fault within moments.']]);}
function mountC17NameVsIp(){c17Mount('tsm',[
  {glow:c17g('pca','--blue')+c17g('sw','--blue')+c17g('gw','--blue')+c17g('fw','--blue')+c17g('dns','--blue'),dyn:c17pkt('M 62 124 L 184 124 L 306 124 L 428 124 L 566 190','--blue')+c17lbl(320,266,'step 1: translate the name to an address (DNS)','--blue'),cap:'Every “open this page” is <b>two operations</b>. First: translate the name to an address – that is <b>DNS</b>.'},
  {glow:c17g('pca','--green')+c17g('sw','--green')+c17g('gw','--green')+c17g('fw','--green')+c17g('web','--green'),dyn:c17pkt('M 62 124 L 184 124 L 306 124 L 428 124 L 566 62','--green')+c17lbl(320,266,'step 2: connect to that address','--green'),cap:'The second operation: <b>connect to the address you got</b>. When either fails, the user describes it the same way.'},
  {glow:c17g('dns','--red')+c17g('web','--green'),dyn:c17lbl(320,266,'name no, address yes → search in DNS','--red'),cap:'<b>Name fails, address works</b>: the network is healthy and name resolution is broken. Leave the network, go to DNS.'},
  {glow:c17g('sw','--amber')+c17g('gw','--amber'),dyn:c17lbl(320,266,'neither works → search in the network','--amber'),cap:'<b>Neither works</b>: the problem is in the network. Go back to cables, VLANs, gateway and routes from earlier lessons.'}
]);}
/* ---------- L5M2 — When the resolver is silent ---------- */
function renderC17Resolver(){return c17P('tsn',
  'Say the test from the previous module pointed at names. Now we ask: <b>where exactly does it stall?</b> A recap of the setup. The computer asks a <b>resolver</b> – a server that looks the name up for it and returns an address. The computer usually receives the resolver’s address automatically – by the same mechanism (<b>DHCP</b>) as its IP address and gateway, as you know from the <b>How networks work</b> course. From that come the three most common faults. <b>1) The resolver is down or unreachable.</b> A classic you will meet again and again: the network is perfectly fine, but because nobody turns names into addresses, <b>“nothing works” for everyone</b>. Recall the trap from lesson one – a scope of “it affects everyone” can send you hunting a broken router that is working flawlessly. <b>2) The computer has the wrong resolver configured.</b> The address points at a server that does not exist, or at one that has no answers for your internal names. Typically it shows up with eerie logic: <b>external websites work, but internal company names do not</b> (or the other way round). <b>3) The resolver answers, but the answer is wrong.</b> Either nobody created the record, or it points at an old address. The procedure is the same halving as always. First: <b>does the resolver answer at all?</b> If not, you are back to ordinary reachability hunting – a resolver is just another device on the network with its own cable, VLAN, address and rules. If yes, ask: <b>does it return the right address?</b> And if names fail on one computer while the neighboring one is fine, look at <b>which resolver each of them has configured</b>.',
  [['resolver','the server that looks a name up for a computer and returns an address; its address usually arrives automatically.'],['internal names','company server names known only to the local resolver; a public one cannot translate them.']]);}
function mountC17Resolver(){c17Mount('tsn',[
  {glow:c17g('pca','--blue')+c17g('sw','--blue')+c17g('gw','--blue')+c17g('fw','--blue')+c17g('dns','--blue'),dyn:c17pkt('M 62 124 L 184 124 L 306 124 L 428 124 L 566 190','--blue')+c17lbl(320,266,'the computer asks the resolver for an address','--blue'),cap:'The setup: the computer asks a <b>resolver</b>, which looks the name up and returns an address. Its address usually arrives automatically.'},
  {glow:c17g('dns','--red')+c17g('pca','--amber')+c17g('pcb','--amber'),dyn:c17lbl(320,266,'resolver silent → all suffer, network is fine','--red'),cap:'Fault 1: the <b>resolver is silent</b>. Everyone suffers, yet the network is flawless – exactly the “broken router” trap.'},
  {glow:c17g('pca','--violet')+c17g('web','--green'),dyn:c17lbl(320,266,'wrong resolver: external yes, internal no','--violet'),cap:'Fault 2: the <b>wrong resolver configured</b>. External sites work but internal company names do not – or vice versa.'},
  {glow:c17g('dns','--cyan')+c17g('fw','--cyan')+c17g('gw','--cyan')+c17g('sw','--cyan')+c17g('pca','--cyan'),dyn:c17pkt('M 566 190 L 428 124 L 306 124 L 184 124 L 62 124','--cyan')+c17lbl(320,266,'does it answer at all? and answer correctly?','--cyan'),cap:'Halving here too: <b>does the resolver answer at all?</b> And if so, <b>does it return the right address?</b> Two questions, two directions.'}
]);}
/* ---------- L5M3 — Cache and a stale answer ---------- */
function renderC17Cache(){return c17P('tso',
  'And now a fault that can drive you mad, because it <b>looks as if physics stopped applying</b>: you fix the record and nothing changes. Or worse – it works for you and not for your colleague, though you sit side by side. The explanation is called the <b>cache</b>. Answers to name queries get stored, so the same question need not be asked over and over. The resolver stores them, and so does the computer itself. Every answer carries a <b>TTL</b> – how long it may be considered valid. And until the TTL expires, you keep getting the <b>old, stored</b> answer, even if the truth changed ten times meanwhile. The typical scenario: a server got a new address, you dutifully fixed the record – but users holding the old stored answer <b>keep going to an address where nobody lives anymore</b>. And because everyone’s cache is of a different age, it manifests beautifully absurdly: “it works for some and not for others”, or “it works for me but not for the client”. How do you recognize a cache? By two signs. First: <b>behavior differs by device</b>, not by network. Second: <b>the problem disappears on its own over time</b>, as TTLs expire on individual machines. The cure is to flush the cache (on the computer and on the resolver) and wait for old answers to expire. And a lesson for next time: <b>before you move a service, lower the TTL in advance</b> – the change then spreads fast and this kind of mystery never finds you.',
  [['cache','stored name answers so the same question need not be asked again.'],['TTL','how long a stored answer counts as valid; until it expires even a stale one holds.']])
  +courseCTA('tsoTask','Look at a network that technically works and yet nothing in it does: the task "The network is fine, nothing works (DNS)".','Open the task');}
function mountC17Cache(){c17Mount('tso',[
  {glow:c17g('dns','--green')+c17g('fw','--green')+c17g('gw','--green')+c17g('sw','--green')+c17g('pca','--green'),dyn:c17pkt('M 566 190 L 428 124 L 306 124 L 184 124 L 62 124','--green')+c17lbl(320,266,'the answer is cached with a TTL validity','--green'),cap:'Name answers are stored in a <b>cache</b>, and each carries a <b>TTL</b> – how long it stays valid.'},
  {glow:c17g('web','--amber')+c17g('dns','--amber'),dyn:c17lbl(320,266,'the server has a new address, the record is fixed','--amber'),cap:'The server got a <b>new address</b> and you dutifully fixed the record. Logically it should be done – but it is not.'},
  {glow:c17g('pca','--red')+c17g('pcb','--green'),dyn:c17lbl(320,266,'stale cache: works for some, not for others','--red'),cap:'PC-A holds a <b>stale answer</b> and goes where nobody lives. PC-B has a fresh one. Hence “it works for some”.'},
  {glow:c17g('pca','--cyan')+c17g('dns','--cyan'),dyn:c17lbl(320,266,'flush the cache; next time lower TTL ahead','--cyan'),cap:'The telltale: it differs <b>by device</b> and fades over time. The cure: flush the cache, and next time lower the TTL in advance.'}
]);
  var b=$('tsoTask');if(b)b.onclick=function(){courseTry('dns-down');};
}
/* ---------- L6M1 — Firewall and default deny ---------- */
function renderC17Deny(){return c17P('tsp',
  'One big group of faults remains, for which “broken” is entirely the wrong word: <b>the network is doing exactly what you told it to</b>. You just told it something other than you thought. A firewall works with a list of <b>rules</b> it walks <b>from top to bottom</b> (you know exactly what a rule looks like and why it reads top-down from the <b>Network security</b> course), ending with a <b>default deny</b>: whatever no rule explicitly permits is dropped. This principle is security-wise absolutely right – only what is needed gets allowed – but it causes a typical fault: <b>someone added a new service and forgot to add a rule for it</b>. The symptom is easy to recognize: <b>everything else works, only that one thing does not</b>. The user reaches the web, mail flows, but one specific application is silent. That is nearly the firewall’s signature. How to tell it from a network fault? By two clues. First <b>selectivity</b>: a network fault usually kills everything toward a given target, whereas a rule hits <b>only a certain kind of traffic</b>. Second the <b>failure mode</b>: dropped traffic often shows up as a long wait and then a give-up, because a dropped packet sends nobody anything. And take this advice to heart: when you find a rule is to blame, <b>do not just write “allow everything”</b>. Add the <b>narrowest possible</b> rule – a specific source, a specific target, a specific service. A broad “allow all” removes the fault and simultaneously opens a hole nobody will remember in a month.',
  [['default deny','whatever no rule explicitly permits is dropped; security-wise right, but a rule is easy to forget.'],['selectivity','a rule hits only a certain kind of traffic, while a network fault usually kills everything to the target.']]);}
function mountC17Deny(){c17Mount('tsp',[
  {glow:c17g('pca','--green')+c17g('sw','--green')+c17g('gw','--green')+c17g('fw','--green')+c17g('web','--green'),dyn:c17pkt('M 62 124 L 184 124 L 306 124 L 428 124 L 566 62','--green')+c17lbl(320,266,'permitted traffic passes without trouble','--green'),cap:'A firewall walks its rules <b>from top to bottom</b>. What is explicitly permitted passes without trouble.'},
  {glow:c17g('fw','--red')+c17g('dns','--red'),dyn:c17lbl(320,266,'default deny: unpermitted traffic is dropped','--red'),cap:'At the end sits the <b>default deny</b>: what no rule permits is dropped. A new service without a rule stays silent.'},
  {glow:c17g('web','--green')+c17g('dns','--red'),dyn:c17lbl(320,266,'everything else runs, only that one thing fails','--amber'),cap:'The firewall’s signature: <b>everything else works, only that one thing does not</b>. A network fault would kill it all.'},
  {glow:c17g('fw','--cyan'),dyn:c17lbl(320,266,'add the narrowest rule, not “allow all”','--cyan'),cap:'The fix: add the <b>narrowest possible rule</b> – a specific source, target and service. “Allow all” opens a hole for months.'}
]);}
/* ---------- L6M2 — Shadowing rule ---------- */
function renderC17Shadow(){return c17P('tsq',
  'This case is the most frustrating of all, because <b>the rule you need is there</b> – and still does not apply. Recall that a firewall reads rules <b>top to bottom</b> and uses the <b>first</b> one matching the traffic; it never even reads the rest. So when a <b>broader</b> rule sits above yours and matches the same traffic, that one decides and your rule is <b>never used</b>. It is called a <b>shadowing rule</b> (and the shadowed one a <b>dead rule</b>). The most common shape: a broad deny at the top (“block everything to this network”) and a specific permit below (“allow the server on this port”). The configuration looks perfectly reasonable, a person reads it and swears access is permitted – it just does not work. The opposite, security-wise worse direction exists too: a broad permit at the top shadowing a specific deny below it. You then believe you are blocking something while it has been passing all along – a hole nobody sees until somebody uses it. How to find shadowing? Take <b>concrete traffic</b> (from where, to where, which service) and walk the list <b>top to bottom</b> exactly as the firewall does. The first matching rule is the one in force. It is usually a different one than you expected. The practical lesson: <b>specific rules belong at the top, general ones at the bottom</b>. And after every change verify what works – including what must not.',
  [['shadowing rule','a broader rule higher in the list that decides before yours is ever reached.'],['dead rule','a rule never reached because something above it shadows it.']]);}
function mountC17Shadow(){c17Mount('tsq',[
  {glow:c17g('fw','--blue'),dyn:c17lbl(320,266,'the firewall reads top down and uses the first match','--blue'),cap:'The firewall reads rules <b>top to bottom</b> and uses the <b>first</b> one matching the traffic. It never reads the rest.'},
  {glow:c17g('fw','--red')+c17g('web','--red'),dyn:c17lbl(320,266,'a broad deny on top decides first','--red'),cap:'A <b>broad deny</b> sits on top, matching the same traffic. It decides – and your permit is never used at all.'},
  {glow:c17g('fw','--amber'),dyn:c17lbl(320,266,'your rule is dead: it is never reached','--amber'),cap:'Your rule is <b>dead</b>: it exists, it looks right, but it is never reached. Hence the frustration.'},
  {glow:c17g('pca','--cyan')+c17g('sw','--cyan')+c17g('gw','--cyan')+c17g('fw','--cyan')+c17g('web','--green'),dyn:c17pkt('M 62 124 L 184 124 L 306 124 L 428 124 L 566 62','--cyan')+c17lbl(320,266,'specific rules up top, general ones below','--cyan'),cap:'Fix and prevention: <b>specific rules to the top, general ones below</b>. And after the change verify what must not work too.'}
]);}
/* ---------- L6M3 — When nothing helps ---------- */
function renderC17Escalate(){return c17P('tsr',
  'The last module is about a situation that will find you sooner or later: <b>you went through everything and still do not know</b>. First the good news – this is not a failure. Only one reaction is wrong: desperately trying random changes. Proceed in three steps instead. <b>1) Isolate.</b> Simplify the situation until the problem disappears. Connect the device directly, remove an intermediate device, try another cable, another port, another computer in the same spot, the same computer in another spot. Each such swap <b>splits the world in half</b> – exactly what you need. <b>2) Document.</b> Write down what you verified and with what result, including what <b>worked</b>. When you hand the case on, this is the most valuable thing you can give – you spare the next person repeating everything you already did. And when the same problem returns in a year, you will thank yourself. <b>3) Escalate.</b> Hand it on when you run out of authority (you may not touch the suspect device), of knowledge (you are on technology you do not know), or when <b>the impact grows faster than your progress</b>. Escalation is not an admission of defeat, it is the right decision. And two things at the very end. <b>Do not forget the possibility that something changed</b> – for mysteries that arose “by themselves” it pays to ask who touched what recently. And once you clear the fault, <b>restore everything you temporarily disabled or permitted along the way</b>. Unfinished cleanup after troubleshooting is the quietest security hole there is.',
  [['isolation','simplifying the situation until the problem vanishes; each swap halves the suspects.'],['escalation','handing the case on when authority or knowledge runs out, or impact outgrows progress.'],['post-fix cleanup','restoring everything temporarily disabled or permitted; otherwise a quiet security hole remains.']])
  +courseCTA('tsrTask','Untangle a rule order where the one rule you need never gets a say: the task "Shadowed rule: fix the ACL order".','Open the task');}
function mountC17Escalate(){c17Mount('tsr',[
  {glow:c17g('pca','--amber')+c17g('sw','--amber')+c17g('gw','--amber')+c17g('fw','--amber'),dyn:c17lbl(320,266,'you checked everything and still do not know','--amber'),cap:'You went through physics, VLANs, addresses, names and rules – and still nothing. Not a failure; just do not start guessing.'},
  {glow:c17g('pca','--blue')+c17g('sw','--blue')+c17g('gw','--blue'),dyn:c17pkt('M 62 124 L 306 124','--blue')+c17lbl(320,266,'isolate: skip a device, swap one piece','--blue'),cap:'<b>Isolate</b>: connect directly, skip a device, swap the cable, port or computer. Each swap splits the world in half.'},
  {glow:c17g('pcb','--violet')+c17g('sw','--violet'),dyn:c17lbl(320,266,'document what worked, too','--violet'),cap:'<b>Document</b> the verified steps including what <b>worked</b>. Whoever takes over need not repeat your work.'},
  {glow:c17g('fw','--cyan')+c17g('web','--cyan')+c17g('dns','--cyan'),dyn:c17lbl(320,266,'escalate in time and clean up afterwards','--cyan'),cap:'<b>Escalate</b> when authority or knowledge runs out. And after the fix <b>restore everything</b> you temporarily disabled or permitted.'}
]);
  var b=$('tsrTask');if(b)b.onclick=function(){courseTry('shadow-rule');};
}

